import{c as t,Q as e,j as r,m as n}from"./chunks/framework.BnKG8mJY.js";const k=JSON.parse('{"title":"Dashboard Overview","description":"","frontmatter":{"title":"Dashboard Overview","outline":"deep"},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),i={name:"guide/dashboard.md"};function s(o,a,l,d,h,u){return e(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="dashboard-overview" tabindex="-1">Dashboard Overview <a class="header-anchor" href="#dashboard-overview" aria-label="Permalink to &quot;Dashboard Overview&quot;">​</a></h1><h2 id="ringkasan-dashboard" tabindex="-1">Ringkasan Dashboard <a class="header-anchor" href="#ringkasan-dashboard" aria-label="Permalink to &quot;Ringkasan Dashboard&quot;">​</a></h2><p>Dashboard adalah halaman utama setelah login. Menampilkan ringkasan performa operasional dan finansial dalam satu layar, termasuk metrik penjualan, biaya, dan aktivitas terbaru.</p><h3 id="komponen-utama" tabindex="-1">Komponen Utama <a class="header-anchor" href="#komponen-utama" aria-label="Permalink to &quot;Komponen Utama&quot;">​</a></h3><p>Dashboard terdiri dari beberapa section yang bisa di-collapse/expand:</p><ol><li><strong>Ringkasan Dashboard</strong> — Metrik utama dan grafik ringkasan</li><li><strong>Expiry Alerts</strong> — Peringatan dokumen/lisensi yang akan expired</li><li><strong>Statistics Sales Cost</strong> — Grafik tren Sales Cost</li><li><strong>Statistics Subcontractor Cost</strong> — Grafik tren Subcontractor</li></ol><h2 id="ringkasan-metrik-sales-cost-summary" tabindex="-1">Ringkasan Metrik (Sales Cost Summary) <a class="header-anchor" href="#ringkasan-metrik-sales-cost-summary" aria-label="Permalink to &quot;Ringkasan Metrik (Sales Cost Summary)&quot;">​</a></h2><h3 id="filter-bulan-tahun" tabindex="-1">Filter Bulan &amp; Tahun <a class="header-anchor" href="#filter-bulan-tahun" aria-label="Permalink to &quot;Filter Bulan &amp; Tahun&quot;">​</a></h3><ul><li>Pilih bulan dan tahun menggunakan dropdown di bagian atas</li><li>Perubahan filter memperbarui semua metrik dan grafik secara otomatis</li><li>Tersedia tombol <strong>Print Ringkasan</strong> untuk mencetak laporan bulan terpilih</li></ul><h3 id="metrik-yang-ditampilkan" tabindex="-1">Metrik yang Ditampilkan <a class="header-anchor" href="#metrik-yang-ditampilkan" aria-label="Permalink to &quot;Metrik yang Ditampilkan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metrik</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Sales</td><td>Total pendapatan periode terpilih</td></tr><tr><td>Total Cost</td><td>Total biaya operasional</td></tr><tr><td>Gross Profit</td><td>Selisih antara Sales dan Total Cost</td></tr></tbody></table><h3 id="indikator-perubahan" tabindex="-1">Indikator Perubahan <a class="header-anchor" href="#indikator-perubahan" aria-label="Permalink to &quot;Indikator Perubahan&quot;">​</a></h3><ul><li>Menampilkan persentase perubahan dibanding periode sebelumnya</li><li>Warna hijau = naik, merah = turun</li></ul><h2 id="monthly-target" tabindex="-1">Monthly Target <a class="header-anchor" href="#monthly-target" aria-label="Permalink to &quot;Monthly Target&quot;">​</a></h2><p>Grafik target bulanan menampilkan perbandingan realisasi vs target per bulan dalam satu tahun.</p><h2 id="monthly-sale" tabindex="-1">Monthly Sale <a class="header-anchor" href="#monthly-sale" aria-label="Permalink to &quot;Monthly Sale&quot;">​</a></h2><p>Grafik penjualan bulanan menampilkan volume transaksi Sales Cost dan Subcontractor per bulan.</p><h2 id="customer-demographic" tabindex="-1">Customer Demographic <a class="header-anchor" href="#customer-demographic" aria-label="Permalink to &quot;Customer Demographic&quot;">​</a></h2><p>Menampilkan sebaran pelanggan berdasarkan lokasi/area untuk memahami fokus pasar.</p><h2 id="recent-orders" tabindex="-1">Recent Orders <a class="header-anchor" href="#recent-orders" aria-label="Permalink to &quot;Recent Orders&quot;">​</a></h2><p>Daftar transaksi terbaru yang masuk ke sistem.</p><h2 id="expiry-alerts" tabindex="-1">Expiry Alerts <a class="header-anchor" href="#expiry-alerts" aria-label="Permalink to &quot;Expiry Alerts&quot;">​</a></h2><p>Peringatan otomatis untuk dokumen kendaraan atau lisensi yang mendekati masa berlaku habis. Membantu admin mengambil tindakan sebelum expired.</p><h2 id="statistics-sales-cost" tabindex="-1">Statistics Sales Cost <a class="header-anchor" href="#statistics-sales-cost" aria-label="Permalink to &quot;Statistics Sales Cost&quot;">​</a></h2><p>Grafik area yang menampilkan tren:</p><ul><li><strong>Sales</strong> (pendapatan)</li><li><strong>Total Cost</strong> (biaya)</li><li><strong>Gross Profit</strong> (margin)</li></ul><p>Filter tersedia: Monthly, Quarterly, Annually.</p><h2 id="statistics-subcontractor-cost" tabindex="-1">Statistics Subcontractor Cost <a class="header-anchor" href="#statistics-subcontractor-cost" aria-label="Permalink to &quot;Statistics Subcontractor Cost&quot;">​</a></h2><p>Grafik serupa untuk transaksi subcontractor dengan format yang sama.</p><h2 id="interaksi-dashboard" tabindex="-1">Interaksi Dashboard <a class="header-anchor" href="#interaksi-dashboard" aria-label="Permalink to &quot;Interaksi Dashboard&quot;">​</a></h2><ul><li><strong>Collapse/Expand</strong>: Klik tombol panah untuk menyembunyikan/menampilkan section</li><li><strong>Collapse All / Expand All</strong>: Tombol cepat untuk semua section sekaligus</li><li><strong>Print Ringkasan</strong>: Mencetak section ringkasan dengan format yang rapi</li><li>State collapse/expand tersimpan di browser (localStorage)</li></ul><h2 id="akses-berdasarkan-role" tabindex="-1">Akses Berdasarkan Role <a class="header-anchor" href="#akses-berdasarkan-role" aria-label="Permalink to &quot;Akses Berdasarkan Role&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Akses Dashboard</th></tr></thead><tbody><tr><td>Admin</td><td>Full access — semua section dan metrik</td></tr><tr><td>User</td><td>Full access — semua section dan metrik</td></tr><tr><td>Mekanik</td><td>Full access — semua section dan metrik</td></tr><tr><td>CS</td><td>Tidak bisa akses Dashboard, redirect ke Schedule Pengiriman</td></tr></tbody></table>',33)])])}const b=t(i,[["render",s]]);export{k as __pageData,b as default};
